static void make_textures(void) {
    mk_brick(); mk_tech(); mk_floor(); mk_ceil(); mk_plank(); mk_concrete(); mk_tile();
    mk_metal(); mk_skin(); mk_flash(); mk_med(); mk_ammo();
    mk_enemy(texZombie, 96, 110, 70, 120, 160, 100, 255, 40, 20, 0);
    /* Fotoğraftaki kıyafet ve sansürlü yüz: tüm normal zombiler bu dokuyu kullanır. */
    memcpy(texZombie, mustiZombieTexture, sizeof(texZombie));   /* zombi: yesil-kahve */
    /* Siyah ceset dokusu: zombinin seffaflik maskesini koru, gorunen pikselleri siyaha boya. */
    for (int i = 0; i < TS * TS; i++) {
        unsigned int a = texZombie[i] & 0xff000000u;
        texZombieDead[i] = a ? (a | 0x00000000u) : 0;
    }
    sceKernelDcacheWritebackRange(texZombieDead, sizeof(texZombieDead));
    mk_enemy(texImp, 150, 60, 40, 190, 90, 60, 255, 230, 40, 1);       /* iblis: kirmizi, boynuzlu */
    /* Uzaktan saldiran zombiler kullanicinin ikinci fotografini kullanir. */
    memcpy(texImp, rangedZombieTexture, sizeof(texImp));
    mk_enemy(texBoss, 80, 40, 110, 120, 70, 140, 80, 255, 80, 1);      /* patron: mor, yesil gozlu */
    sceKernelDcacheWritebackAll();
}
static void bind(unsigned int *t) {
    sceGuTexMode(GU_PSM_8888, 0, 0, 0);
    sceGuTexImage(0, TS, TS, TS, t);
}

