/* ---------------------------------------------------------- ses sistemi (silahlar + olum efekti) */
#define DEATH_AUDIO_CHANNEL_SAMPLES 2048
static volatile int sound_requested = 0; /* 1 M249, 2 shotgun, 3 pistol, 4 death, 5 footsteps, 6 menu music, 7 menu select */
static volatile int menu_music_active = 0;
static int death_audio_channel = -1;

static void output_pcm(const short *pcm, int samples) {
    static short __attribute__((aligned(64))) chunk[DEATH_AUDIO_CHANNEL_SAMPLES];
    for (int offset = 0; offset < samples; offset += DEATH_AUDIO_CHANNEL_SAMPLES) {
        int count = samples - offset;
        if (count > DEATH_AUDIO_CHANNEL_SAMPLES) count = DEATH_AUDIO_CHANNEL_SAMPLES;
        memcpy(chunk, pcm + offset, count * sizeof(short));
        if (count < DEATH_AUDIO_CHANNEL_SAMPLES)
            memset(chunk + count, 0, (DEATH_AUDIO_CHANNEL_SAMPLES - count) * sizeof(short));
        sceAudioOutputPannedBlocking(death_audio_channel,
                                     PSP_AUDIO_VOLUME_MAX,
                                     PSP_AUDIO_VOLUME_MAX, chunk);
    }
}

static void output_menu_music_loop(void) {
    static short __attribute__((aligned(64))) chunk[DEATH_AUDIO_CHANNEL_SAMPLES];
    while (menu_music_active && sound_requested == 0) {
        for (int offset = 0; offset < MENU_MUSIC_SAMPLES && menu_music_active && sound_requested == 0; offset += DEATH_AUDIO_CHANNEL_SAMPLES) {
            int count = MENU_MUSIC_SAMPLES - offset;
            if (count > DEATH_AUDIO_CHANNEL_SAMPLES) count = DEATH_AUDIO_CHANNEL_SAMPLES;
            memcpy(chunk, menu_music_pcm + offset, count * sizeof(short));
            if (count < DEATH_AUDIO_CHANNEL_SAMPLES) memset(chunk + count, 0, (DEATH_AUDIO_CHANNEL_SAMPLES-count)*sizeof(short));
            sceAudioOutputPannedBlocking(death_audio_channel, PSP_AUDIO_VOLUME_MAX, PSP_AUDIO_VOLUME_MAX, chunk);
        }
    }
}

static int death_audio_thread(SceSize args, void *argp) {
    (void)args; (void)argp;
    death_audio_channel = sceAudioChReserve(PSP_AUDIO_NEXT_CHANNEL,
                                             DEATH_AUDIO_CHANNEL_SAMPLES,
                                             PSP_AUDIO_FORMAT_MONO);
    if (death_audio_channel < 0) return 0;
    while (1) {
        int which = sound_requested;
        if (which) {
            sound_requested = 0;
            if (which == 1) output_pcm(m249_audio_pcm, M249_AUDIO_SAMPLES);
            else if (which == 2) output_pcm(shotgun_audio_pcm, SHOTGUN_AUDIO_SAMPLES);
            else if (which == 3) output_pcm(pistol_audio_pcm, PISTOL_AUDIO_SAMPLES);
            else if (which == 4) output_pcm(death_audio_pcm, DEATH_AUDIO_SAMPLES);
            else if (which == 5) output_pcm(footstep_audio_pcm, FOOTSTEP_AUDIO_SAMPLES);
            else if (which == 6) output_menu_music_loop();
            else if (which == 7) output_pcm(menu_select_pcm, MENU_SELECT_SAMPLES);
        } else if (menu_music_active) {
            output_menu_music_loop();
        } else {
            sceKernelDelayThread(1500);
        }
    }
    return 0;
}

static void init_death_audio(void) {
    int tid = sceKernelCreateThread("moom_audio", death_audio_thread,
                                    0x18, 0x4000, THREAD_ATTR_USER, NULL);
    if (tid >= 0) sceKernelStartThread(tid, 0, NULL);
}

static void play_death_sound(void) { sound_requested = 4; }
static void play_weapon_sound(int which) { sound_requested = which; }

/* ---------------------------------------------------------- oyun durumu */
/* tip: 0 zombi, 1 iblis (uzaktan), 2 patron */
typedef struct { float x, z; int type, hp, state; float cd, hurt, dead; int awake; } Enemy;
typedef struct { float x, z; int type, active; } Item;
#define MAXE 32
static Enemy en[MAXE]; static int nen;
static Item it[MAXE]; static int nit;
static float px, pz, yaw, bob;
static int hp, ammo, kills, total, gstate;      /* gstate: 0 oyun, 1 oldun, 2 bolum bitti */
static int weapon; /* 0 shotgun, 1 dual pistols, 2 M249, 3 crowbar, 4 launcher, 5 AK, 6 sniper */
static int sniper_aim = 0;
static int sniper_zoom = 1; /* 1..3 */
static float footstepTimer = 0.0f;
static int title_screen = 1;
static int menu_selection = 0; /* 0 OYNA, 1 AYARLAR */
static int settings_language = 0;
static int settings_selection = 0; /* 0 dil, 1 silah gorunumu */
static int weapon_view_2d = 0; /* 0: 3D, 1: 2D */
static int level_selection = 0;
static float menu_flash = 0.0f;
static int pending_menu_action = -1;
static float cdFire, fireAnim, flash, dmgf, healf, tsec, levelT;
static float grenade_blast_fx = 0.0f;
static SceCtrlData pad, padp;

static void load_level(int idx, int carry) {
    titan_reset_for_level(idx);
    const Level *L = &LV[idx];
    curLevel = idx; curMap = L->rows; curW = L->w; curH = L->h;
    th = &TH[L->theme];
    nen = 0; nit = 0; nlamp = 0;
    for (int z = 0; z < curH; z++) for (int x = 0; x < curW; x++) {
        char c = curMap[z][x];
        if (c == 'P') { px = x + 0.5f; pz = z + 0.5f; }
        if ((c == 'Z' || c == 'S' || c == 'B') && nen < MAXE) {
            int type = (c == 'Z') ? 0 : ((c == 'S') ? 1 : 2);
            int hpv = (type == 0) ? 60 : ((type == 1) ? 40 : 220);
            Enemy e = {x + 0.5f, z + 0.5f, type, hpv, 0, 1.0f, 0, 0, 0};
            en[nen++] = e;
        }
        if ((c == 'H' || c == 'A') && nit < MAXE) {
            Item i = {x + 0.5f, z + 0.5f, (c == 'H') ? 0 : 1, 1};
            it[nit++] = i;
        }
    }
    for (int z = 0; z < curH; z++) for (int x = 0; x < curW; x++) {
        if (!is_wall_cell(x, z) && (x % 4) == 2 && (z % 4) == 2 && nlamp < MAXL) {
            int k = (int)(hash2(x, z) % 3u);
            Lamp l = {x + 0.5f, z + 0.5f, th->pal[k][0], th->pal[k][1], th->pal[k][2]};
            lamps[nlamp++] = l;
        }
    }
    build_world();
    yaw = L->yaw; bob = 0;
    if (carry) {
        hp += 30; if (hp > 100) hp = 100;
        ammo += 12; if (ammo > 99) ammo = 99;
    } else { hp = 100; ammo = 24; }
    kills = 0; total = nen; gstate = 0;
    weapon = 0;
    footstepTimer = 0.0f;
    cdFire = 0; fireAnim = 0; flash = 0; dmgf = 0; healf = 0;
    levelT = 3.0f;
}

static void damage(int n) {
    hp -= n; dmgf = 0.35f;
    if (hp <= 0) { hp = 0; gstate = 1; }
}

static void shoot(int baseDamage) {
    float fx = sinf(yaw), fz = -cosf(yaw), rx = cosf(yaw), rz = sinf(yaw);
    for (int i = 0; i < nen; i++) {
        Enemy *e = &en[i];
        if (e->state != 0) continue;
        float dx = e->x - px, dz = e->z - pz;
        float d = sqrtf(dx * dx + dz * dz);
        if (d < 12.0f && los(px, pz, e->x, e->z)) e->awake = 1;
        float along = dx * fx + dz * fz;
        if (along < 0.2f) continue;
        float lat = dx * rx + dz * rz;
        float tol = (weapon == 6) ? (0.045f + along * 0.004f) : (0.38f + along * 0.07f + ((e->type == 2) ? 0.25f : 0.0f));
        if (fabsf(lat) < tol && los(px, pz, e->x, e->z)) {
            int dmg = (int)((float)baseDamage / (1.0f + 0.35f * along));
            if (dmg < 12) dmg = 12;
            e->hp -= dmg; e->hurt = 0.15f; e->awake = 1;
            if (e->hp <= 0) {
                e->state = 1; e->dead = 0; kills++; play_death_sound();
                ammo += (e->type == 2) ? 12 : 5;
                if (ammo > 99) ammo = 99;
            }
        }
    }
}

static void melee_hit(int baseDamage) {
    float fx = sinf(yaw), fz = -cosf(yaw);
    for (int i = 0; i < nen; i++) {
        Enemy *e = &en[i];
        if (e->state != 0) continue;
        float dx = e->x - px, dz = e->z - pz;
        float d = sqrtf(dx * dx + dz * dz);
        if (d > 1.55f || d < 0.01f) continue;
        float facing = (dx * fx + dz * fz) / d;
        if (facing < 0.25f || !los(px, pz, e->x, e->z)) continue;
        e->hp -= baseDamage; e->hurt = 0.18f; e->awake = 1;
        if (e->hp <= 0) {
            e->state = 1; e->dead = 0; kills++; play_death_sound();
            ammo += (e->type == 2) ? 12 : 5; if (ammo > 99) ammo = 99;
        }
    }
}

static void grenade_blast(void) {
    grenade_blast_fx = 0.62f;
    /* Patlama alanindaki tum dusmanlar tek vurusla etkisiz kalir. */
    for (int i = 0; i < nen; i++) {
        Enemy *e = &en[i];
        if (e->state != 0) continue;
        float dx = e->x - px, dz = e->z - pz;
        float d = sqrtf(dx * dx + dz * dz);
        if (d > 4.8f || !los(px, pz, e->x, e->z)) continue;
        e->hp = 0; e->hurt = 0.25f; e->awake = 1;
        if (e->hp <= 0) {
            e->state = 1; e->dead = 0; kills++; play_death_sound();
            ammo += (e->type == 2) ? 12 : 5;
            if (ammo > 99) ammo = 99;
        }
    }
}

static void update(float dt) {
    if (gstate == 0) { titan_update(dt, px, pz, &gstate); }
    tsec += dt;
    if (grenade_blast_fx > 0.0f) { grenade_blast_fx -= dt; if (grenade_blast_fx < 0.0f) grenade_blast_fx = 0.0f; }
    int newStart = (pad.Buttons & PSP_CTRL_START) && !(padp.Buttons & PSP_CTRL_START);
    int newCross = (pad.Buttons & PSP_CTRL_CROSS) && !(padp.Buttons & PSP_CTRL_CROSS);
    int newCircle = (pad.Buttons & PSP_CTRL_CIRCLE) && !(padp.Buttons & PSP_CTRL_CIRCLE);
    int newUp = (pad.Buttons & PSP_CTRL_UP) && !(padp.Buttons & PSP_CTRL_UP);
    int newDown = (pad.Buttons & PSP_CTRL_DOWN) && !(padp.Buttons & PSP_CTRL_DOWN);
    int newSquare = (pad.Buttons & PSP_CTRL_SQUARE) && !(padp.Buttons & PSP_CTRL_SQUARE);
    int newR = (pad.Buttons & PSP_CTRL_RTRIGGER) && !(padp.Buttons & PSP_CTRL_RTRIGGER);
    if (menu_flash > 0.0f) {
        menu_flash -= dt;
        if (menu_flash <= 0.0f) {
            menu_flash = 0.0f;
            if (pending_menu_action == 0) { level_selection = 0; gstate = 5; }
            else if (pending_menu_action == 1) { settings_selection = 0; gstate = 4; }
            pending_menu_action = -1;
        }
    }
    if (gstate == 3) {
        if (menu_flash <= 0.0f) {
            if (newUp || newDown) menu_selection = 1 - menu_selection;
            if (newCross || newStart) {
                sound_requested = 7;
                menu_flash = 0.14f;
                pending_menu_action = menu_selection;
            }
        }
        return;
    }
    if (gstate == 5) {
        if (newUp) { level_selection--; if (level_selection < 0) level_selection = NLEV - 1; sound_requested = 7; }
        if (newDown) { level_selection++; if (level_selection >= NLEV) level_selection = 0; sound_requested = 7; }
        if (newCross || newStart) { menu_music_active = 0; sound_requested = 7; load_level(level_selection, 0); }
        if (newCircle) { sound_requested = 7; gstate = 3; }
        return;
    }
    if (gstate == 4) {
        if (newUp) { settings_selection = 1 - settings_selection; sound_requested = 7; }
        if (newDown) { settings_selection = 1 - settings_selection; sound_requested = 7; }
        if (newCross) {
            sound_requested = 7;
            if (settings_selection == 0) settings_language = 1 - settings_language;
            else weapon_view_2d = 1 - weapon_view_2d;
        }
        if (newCircle || newStart) { sound_requested = 7; gstate = 3; }
        return;
    }
    if (gstate != 0) {
        if (newStart) {
            if (gstate == 1) load_level(curLevel, 0);
            else if (curLevel + 1 < NLEV) load_level(curLevel + 1, 1);
            else load_level(0, 0);
        }
        return;
    }
    if (levelT > 0) levelT -= dt;
    if (weapon == 6 && newDown) sniper_aim = 1 - sniper_aim;
    else if (weapon != 6) sniper_aim = 0;
    if (weapon == 6 && sniper_aim) {
        if (newSquare) { sniper_zoom++; if (sniper_zoom > 3) sniper_zoom = 1; }
        if (newCircle) { sniper_zoom--; if (sniper_zoom < 1) sniper_zoom = 3; }
    }

    float mv = 0, st = 0, tn = 0;
    float ay = ((float)pad.Ly - 128.0f) / 128.0f, ax = ((float)pad.Lx - 128.0f) / 128.0f;
    if (fabsf(ay) > 0.2f) mv -= ay;
    if (fabsf(ax) > 0.2f) tn += ax;
    if (pad.Buttons & PSP_CTRL_UP) mv += 1;
    if (pad.Buttons & PSP_CTRL_DOWN) mv -= 1;
    if (pad.Buttons & PSP_CTRL_RIGHT) tn += 1;
    if (pad.Buttons & PSP_CTRL_LEFT) tn -= 1;
    /* R1 silah degistirir; L1 sola yan yurume olarak kalir. */
    if (pad.Buttons & PSP_CTRL_LTRIGGER) st -= 1;
    if (newR) { weapon = (weapon + 1) % 7; sniper_aim = 0; }
    if (mv > 1) mv = 1;
    if (mv < -1) mv = -1;
    if (tn > 1) tn = 1;
    if (tn < -1) tn = -1;

    yaw += tn * 2.6f * dt;
    float speed = ((pad.Buttons & PSP_CTRL_CIRCLE) && !(weapon == 6 && sniper_aim)) ? 4.0f : 2.6f;
    float fx = sinf(yaw), fz = -cosf(yaw), rx = cosf(yaw), rz = sinf(yaw);
    float dx = (fx * mv + rx * st) * speed * dt, dz = (fz * mv + rz * st) * speed * dt;
    if (!blocked(px + dx, pz, 0.2f)) px += dx;
    if (!blocked(px, pz + dz, 0.2f)) pz += dz;
    if (fabsf(mv) > 0.05f || fabsf(st) > 0.05f) {
        bob += dt * (speed > 3.0f ? 11.0f : 8.0f);
        footstepTimer -= dt;
        if (footstepTimer <= 0.0f) {
            if (sound_requested == 0) play_weapon_sound(5);
            footstepTimer = (speed > 3.0f) ? 0.34f : 0.46f;
        }
    } else footstepTimer = 0.0f;

    /* ates */
    if (cdFire > 0) cdFire -= dt;
    if (fireAnim > 0) { fireAnim -= dt / 0.6f; if (fireAnim < 0) fireAnim = 0; }
    if (flash > 0) flash -= dt;
    if (dmgf > 0) dmgf -= dt;
    if (healf > 0) healf -= dt;
    int fire = (pad.Buttons & ((weapon == 6 && sniper_aim) ? PSP_CTRL_CROSS : (PSP_CTRL_CROSS | PSP_CTRL_SQUARE))) != 0;
    if (fire && cdFire <= 0) {
        if (weapon == 3) {
            cdFire = 0.52f; fireAnim = 1.0f; flash = 0.0f;
            melee_hit(58);
        } else if (ammo > 0) {
            ammo--;
            cdFire = (weapon == 0) ? 0.60f : ((weapon == 1) ? 0.22f : ((weapon == 4) ? 0.85f : ((weapon == 6) ? 0.95f : 0.095f)));
            fireAnim = 1.0f; flash = (weapon == 4) ? 0.0f : 0.08f;
            if (weapon == 4) grenade_blast();
            else {
                play_weapon_sound(weapon == 0 ? 2 : (weapon == 1 ? 3 : 1));
                shoot(weapon == 0 ? 70 : (weapon == 1 ? 28 : (weapon == 5 ? 24 : (weapon == 6 ? 220 : 16))));
            }
        } else cdFire = 0.3f;
    }

    /* dusmanlar */
    for (int i = 0; i < nen; i++) {
        Enemy *e = &en[i];
        if (e->state == 1) { e->dead += dt; if (e->dead > 0.6f) e->state = 2; continue; }
        if (e->state == 2) continue;
        if (e->hurt > 0) e->hurt -= dt;
        e->cd -= dt;
        float ex = px - e->x, ez = pz - e->z;
        float d = sqrtf(ex * ex + ez * ez);
        int vis = (d < 16.0f) && los(e->x, e->z, px, pz);
        if (vis && d < 12.0f) e->awake = 1;
        if (!e->awake) continue;
        float sp = (e->type == 0) ? 1.5f : ((e->type == 1) ? 1.0f : 0.8f);
        float stop = (e->type == 0) ? 0.8f : ((e->type == 1) ? 5.0f : 6.0f);
        float rad = (e->type == 2) ? 0.4f : 0.28f;
        if (d > stop && d > 0.01f) {
            float mx = ex / d * sp * dt, mz = ez / d * sp * dt;
            if (!blocked(e->x + mx, e->z, rad)) e->x += mx;
            if (!blocked(e->x, e->z + mz, rad)) e->z += mz;
        }
        if (e->type == 0 && d < 1.0f && e->cd <= 0) { damage(10); e->cd = 0.9f; }
        if (e->type == 1 && vis && d < 9.0f && e->cd <= 0) {
            e->cd = 1.5f;
            if (rand() % 100 < 65) damage(4 + rand() % 3);
        }
        if (e->type == 2 && vis && d < 11.0f && e->cd <= 0) {
            e->cd = 1.1f;
            if (rand() % 100 < 70) damage(5 + rand() % 4);
        }
    }

    /* esyalar */
    for (int i = 0; i < nit; i++) {
        if (!it[i].active) continue;
        float dx2 = it[i].x - px, dz2 = it[i].z - pz;
        if (dx2 * dx2 + dz2 * dz2 < 0.36f) {
            if (it[i].type == 0) { if (hp < 100) { hp += 25; if (hp > 100) hp = 100; healf = 0.3f; it[i].active = 0; } }
            else { ammo += 8; if (ammo > 99) ammo = 99; healf = 0.2f; it[i].active = 0; }
        }
    }

    if (kills >= total) gstate = 2;
}

/* ---------------------------------------------------------- cizim yardimcilari */
static void sprite(float x, float z, float w, float h, unsigned int col) {
    float rx = cosf(yaw) * w * 0.5f, rz = sinf(yaw) * w * 0.5f;
    Vertex *v = (Vertex *)sceGuGetMemory(6 * sizeof(Vertex));
    v[0] = (Vertex){0, 1, col, x - rx, 0, z - rz};
    v[1] = (Vertex){1, 1, col, x + rx, 0, z + rz};
    v[2] = (Vertex){1, 0, col, x + rx, h, z + rz};
    v[3] = v[0]; v[4] = v[2];
    v[5] = (Vertex){0, 0, col, x - rx, h, z - rz};
    sceGuDrawArray(GU_TRIANGLES, VT, 6, 0, v);
}

static void rect(float x, float y, float w, float h, unsigned int c) {
    V2 *v = (V2 *)sceGuGetMemory(2 * sizeof(V2));
    v[0] = (V2){c, x, y, 0};
    v[1] = (V2){c, x + w, y + h, 0};
    sceGuDrawArray(GU_SPRITES, VT2, 2, 0, v);
}

typedef struct { char c; unsigned char r[5]; } Gl;
static const Gl GLY[] = {
    {'0',{7,5,5,5,7}},{'1',{2,6,2,2,7}},{'2',{7,1,7,4,7}},{'3',{7,1,7,1,7}},{'4',{5,5,7,1,1}},
    {'5',{7,4,7,1,7}},{'6',{7,4,7,5,7}},{'7',{7,1,1,1,1}},{'8',{7,5,7,5,7}},{'9',{7,5,7,1,7}},
    {'A',{2,5,7,5,5}},{'B',{6,5,6,5,6}},{'C',{7,4,4,4,7}},{'D',{6,5,5,5,6}},{'E',{7,4,7,4,7}},
    {'F',{7,4,7,4,4}},{'G',{7,4,5,5,7}},{'H',{5,5,7,5,5}},{'I',{7,2,2,2,7}},{'J',{1,1,1,5,7}},
    {'K',{5,5,6,5,5}},{'L',{4,4,4,4,7}},{'M',{5,7,7,5,5}},{'N',{7,5,5,5,5}},{'O',{7,5,5,5,7}},
    {'P',{7,5,7,4,4}},{'Q',{7,5,5,7,1}},{'R',{6,5,6,5,5}},{'S',{7,4,7,1,7}},{'T',{7,2,2,2,2}},
    {'U',{5,5,5,5,7}},{'V',{5,5,5,5,2}},{'W',{5,5,5,7,5}},{'X',{5,5,2,5,5}},{'Y',{5,5,2,2,2}},
    {'Z',{7,1,2,4,7}},{'/',{1,1,2,4,4}},{'-',{0,0,7,0,0}},{':',{0,2,0,2,0}}
};
static void text(float x, float y, float s, const char *str, unsigned int c) {
    for (; *str; str++) {
        for (unsigned int k = 0; k < sizeof(GLY) / sizeof(GLY[0]); k++) {
            if (GLY[k].c == *str) {
                for (int r = 0; r < 5; r++) for (int col = 0; col < 3; col++)
                    if (GLY[k].r[r] & (4 >> col)) rect(x + col * s, y + r * s, s, s, c);
                break;
            }
        }
        x += 4 * s;
    }
}
static void text_c(float y, float s, const char *str, unsigned int c) {
    float w = 4.0f * s * (float)strlen(str) - s;
    text((SCR_W - w) * 0.5f, y, s, str, c);
}

static void draw_grenade_explosion(void) {
    if (grenade_blast_fx <= 0.0f) return;
    float progress = 1.0f - grenade_blast_fx / 0.62f;
    float radius = 12.0f + progress * 88.0f;
    float inner = radius * (0.48f - progress * 0.12f);
    int alpha = (int)(210.0f * (1.0f - progress));
    if (alpha < 0) alpha = 0;
    if (alpha > 210) alpha = 210;
    if (progress < 0.22f)
        rect(0, 0, SCR_W, SCR_H, RGBA(255, 235, 175, (int)(95.0f * (1.0f - progress / 0.22f))));
    for (int y = -(int)radius; y <= (int)radius; y += 5) {
        float outerSq = radius * radius - (float)(y * y);
        if (outerSq <= 0.0f) continue;
        float outerW = sqrtf(outerSq);
        float innerSq = inner * inner - (float)(y * y);
        float py = 132.0f + (float)y;
        if (innerSq > 0.0f) {
            float innerW = sqrtf(innerSq);
            rect(240.0f - outerW, py, outerW - innerW, 5, RGBA(255, 105, 25, alpha));
            rect(240.0f + innerW, py, outerW - innerW, 5, RGBA(255, 105, 25, alpha));
        } else {
            rect(240.0f - outerW, py, outerW * 2.0f, 5, RGBA(255, 145, 35, alpha));
        }
    }
    if (progress < 0.55f) {
        float core = 18.0f * (1.0f - progress / 0.55f);
        rect(240.0f - core, 132.0f - core, core * 2.0f, core * 2.0f,
             RGBA(255, 225, 115, (int)(190.0f * (1.0f - progress / 0.55f))));
    }
    if (progress > 0.18f) {
        int smoke = (int)(105.0f * (1.0f - progress));
        float drift = progress * 17.0f;
        rect(205.0f - drift, 110.0f - drift, 28, 22, RGBA(75, 78, 82, smoke));
        rect(240.0f + drift, 102.0f - drift * 0.7f, 32, 25, RGBA(90, 88, 82, smoke));
        rect(222.0f, 145.0f + drift, 35, 18, RGBA(65, 68, 73, smoke));
    }
}

static void gun_model(float extraZ) {
    float fa = fireAnim;
    ScePspFVector3 t = {0.16f + sinf(bob) * 0.010f, -0.12f - fabsf(cosf(bob)) * 0.012f, -0.45f + fa * 0.06f + extraZ};
    sceGumMatrixMode(GU_MODEL);
    sceGumLoadIdentity();
    sceGumTranslate(&t);
    sceGumRotateX(fa * 0.12f);
    sceGumRotateY(-0.05f);
    sceGumUpdateMatrix();
}

