/* Title cover: user supplied MOOM Zombie Survival artwork. */
static void draw_cover_screen(void) {
    sceGuDisable(GU_DEPTH_TEST);
    sceGuDisable(GU_FOG);
    sceGuEnable(GU_TEXTURE_2D);
    sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);
    sceGuTexMode(GU_PSM_8888, 0, 0, 0);
    sceGuTexImage(0, 512, 256, 512, moom_cover_tex);
    sceGuTexFilter(GU_LINEAR, GU_LINEAR);
    sceGuTexFunc(GU_TFX_MODULATE, GU_TCC_RGBA);
    typedef struct { float u,v; unsigned int c; float x,y,z; } CoverV;
    CoverV *v = (CoverV *)sceGuGetMemory(4 * sizeof(CoverV));
    unsigned int white = RGBA(255,255,255,255);
    v[0] = (CoverV){0,0,white,20,42,0};
    v[1] = (CoverV){512,0,white,460,42,0};
    v[2] = (CoverV){0,256,white,20,262,0};
    v[3] = (CoverV){512,256,white,460,262,0};
    sceGuDrawArray(GU_TRIANGLE_STRIP, GU_TEXTURE_32BITF | GU_COLOR_8888 | GU_VERTEX_32BITF | GU_TRANSFORM_2D, 4, 0, v);
    sceGuDisable(GU_TEXTURE_2D);
    sceGuDisable(GU_BLEND);
}

