static void draw_level_select_screen(void) {
    sceGuDisable(GU_TEXTURE_2D); sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);
    rect(0, 0, SCR_W, SCR_H, RGBA(5, 7, 12, 245));
    text_c(48, 8, "BOLUM SEC", RGBA(220, 35, 35, 255));
    /* PSP ekraninda tasma olmamasi icin 9 bolumluk kayan liste. */
    int first = level_selection - 4;
    if (first < 0) first = 0;
    if (first > NLEV - 9) first = NLEV - 9;
    if (first < 0) first = 0;
    int last = first + 9;
    if (last > NLEV) last = NLEV;
    for (int i = first; i < last; i++) {
        int y = 72 + (i - first) * 18;
        if (i == level_selection) rect(100, y - 3, 280, 19, RGBA(145, 25, 25, 235));
        char label[48];
        snprintf(label, sizeof(label), "%d. %s", i + 1, LV[i].name);
        text_c(y, 4, label, i == level_selection ? RGBA(255,255,255,255) : RGBA(175,180,190,255));
    }
    text_c(258, 3, "X START   O BACK", RGBA(220,220,220,255));
    sceGuDisable(GU_BLEND);
}

